UPDATE assessment_template_versions tv
SET schema_definition=$schema${"instrument_number":6,"template_name":"Root-Cause & Opportunity Analysis","description":"An advisor-led synthesis instrument that connects evidence across the business assessments, distinguishes symptoms from underlying causes, tests competing explanations and develops evidence-linked improvement opportunities.","schema_status":"active","sections":[{"id":"problem_definition","title":"1. Problem definition & business impact","description":"Define the performance gap or opportunity precisely before attempting to explain it.","questions":[{"key":"rc_problem_statement","label":"Problem or opportunity statement","type":"textarea","required":true,"prompt":"State what is happening, where, to whom and since when. Avoid embedding an assumed cause in the problem statement."},{"key":"rc_expected_state","label":"Expected or desired state","type":"textarea","required":true,"prompt":"Describe the target condition and the basis for expecting it. Distinguish contractual, strategic, historical and aspirational expectations."},{"key":"rc_actual_state","label":"Observed current state","type":"textarea","required":true,"prompt":"Describe measured or observed actual performance, scope, period and source. Mark owner-reported or unverified information."},{"key":"rc_performance_gap","label":"Performance gap and magnitude","type":"textarea","prompt":"Quantify only where the baseline, unit, period, denominator and comparison are valid. Otherwise describe qualitatively and note the gap."},{"key":"rc_affected_stakeholders","label":"Affected customers, employees and stakeholders","type":"textarea","required":true,"prompt":"Identify who experiences the issue or benefit, including customer, employee, supplier, owner and compliance implications."},{"key":"rc_business_consequences","label":"Business consequences and strategic relevance","type":"textarea","required":true,"prompt":"Describe supported financial, operational, commercial, risk, capacity or value consequences. Avoid double counting."}]},{"id":"evidence_register","title":"2. Evidence & assessment crosswalk","description":"Build a traceable evidence base using the prior assessment instruments and source records.","questions":[{"key":"rc_related_instruments","label":"Related assessment instruments and findings","type":"textarea","required":true,"prompt":"Reference relevant findings from Instruments 1–5 by instrument, section/question and finding. Explain how they relate."},{"key":"rc_evidence_sources","label":"Evidence sources reviewed","type":"textarea","required":true,"prompt":"List source documents, system records, interviews, observations, reports and dates. Identify owner and scope where relevant."},{"key":"rc_verified_facts","label":"Verified facts and observations","type":"textarea","required":true,"prompt":"Record only facts directly supported by reviewed evidence. Include source, date, period and scope."},{"key":"rc_owner_reported","label":"Owner / management / employee reported information","type":"textarea","prompt":"Capture statements separately from verified records. Identify speaker role and date where appropriate."},{"key":"rc_contradictions","label":"Conflicting evidence, inconsistencies and limitations","type":"textarea","prompt":"Identify inconsistent records, definitions, time periods, incomplete samples, possible bias and evidence limitations."},{"key":"rc_evidence_confidence","label":"Overall evidence sufficiency","type":"select","required":true,"options":["Strong — multiple relevant sources corroborate key facts","Moderate — useful evidence with material gaps","Limited — primarily reported or indirect evidence","Insufficient — conclusions should be deferred"]}]},{"id":"causal_analysis","title":"3. Root-cause investigation","description":"Move from symptoms to mechanisms and test alternative explanations.","questions":[{"key":"rc_symptoms","label":"Observed symptoms and immediate effects","type":"textarea","required":true,"prompt":"List visible outcomes without assuming why they occur."},{"key":"rc_contributing_factors","label":"Contributing factors","type":"textarea","prompt":"Identify conditions that may increase likelihood or severity. Separate evidence-supported factors from possibilities."},{"key":"rc_root_causes","label":"Candidate root causes","type":"textarea","required":true,"prompt":"Describe underlying process, capability, incentive, resource, governance, market, data or technology mechanisms. Link each to evidence."},{"key":"rc_causal_mechanism","label":"How the proposed cause produces the observed outcome","type":"textarea","required":true,"prompt":"Explain the causal chain step by step. Avoid correlation-only reasoning."},{"key":"rc_alternative_explanations","label":"Alternative explanations considered","type":"textarea","required":true,"prompt":"List plausible competing causes and what evidence would support or weaken each."},{"key":"rc_causal_tests","label":"Tests or analyses used to validate causality","type":"textarea","prompt":"Describe comparisons, sampling, process tracing, interviews, time-series checks, cohort analysis or other tests performed."},{"key":"rc_cause_confidence","label":"Confidence in root-cause conclusion","type":"select","required":true,"options":["High — causal mechanism directly supported and alternatives tested","Moderate — supported explanation, some alternatives unresolved","Low — plausible hypothesis requiring validation","Undetermined — insufficient evidence to identify root cause"]}]},{"id":"cross_dimension","title":"4. Cross-dimensional patterns & dependencies","description":"Identify interactions across financial, operational, organizational, commercial, technology and scalability dimensions.","questions":[{"key":"rc_financial_links","label":"Financial performance connections","type":"textarea","prompt":"Link supported causes to revenue quality, margins, costs, working capital, cash flow or capital needs."},{"key":"rc_operational_links","label":"Operational effectiveness connections","type":"textarea","prompt":"Link causes to workflow, throughput, capacity, quality, controls, service levels or bottlenecks."},{"key":"rc_organizational_links","label":"Organizational effectiveness connections","type":"textarea","prompt":"Link causes to role clarity, skills, accountability, incentives, leadership capacity, culture or key-person dependency."},{"key":"rc_commercial_links","label":"Commercial performance connections","type":"textarea","prompt":"Link causes to positioning, demand, lead quality, conversion, pricing, customer concentration, retention or expansion."},{"key":"rc_technology_links","label":"Technology, data and systems connections","type":"textarea","prompt":"Link causes to system fit, integration, automation, data quality, reporting, access, security or technical debt."},{"key":"rc_scalability_links","label":"Scalability and business value connections","type":"textarea","prompt":"Link causes to repeatability, management dependence, transferability, resilience, growth capacity and business value drivers."},{"key":"rc_dependencies","label":"Dependencies, reinforcing loops and unintended effects","type":"textarea","prompt":"Identify interdependencies, feedback loops, constraints and possible unintended consequences of changing one area."}]},{"id":"opportunity_design","title":"5. Opportunity identification & solution hypotheses","description":"Develop actionable responses that address validated causes rather than symptoms alone.","questions":[{"key":"rc_opportunity_list","label":"Improvement and value-creation opportunities","type":"textarea","required":true,"prompt":"For each opportunity, describe the cause addressed, proposed change, affected process/customer/employee and expected mechanism of benefit."},{"key":"rc_solution_alternatives","label":"Alternative intervention options","type":"textarea","prompt":"Compare process, people, commercial, technology, governance, capability or strategic options. Include no-change where appropriate."},{"key":"rc_expected_outcomes","label":"Expected outcomes and leading indicators","type":"textarea","required":true,"prompt":"Define measurable leading and lagging indicators, baseline needed, time horizon and expected direction. Do not invent impact estimates."},{"key":"rc_required_capabilities","label":"Required capabilities, resources and ownership","type":"textarea","prompt":"Identify skills, capacity, budget, data, systems, decision rights and accountable owner required."},{"key":"rc_change_impact","label":"Customer, employee and organizational change impact","type":"textarea","required":true,"prompt":"Assess workload, role changes, training, service continuity, customer experience, adoption and communication needs."},{"key":"rc_solution_risks","label":"Implementation risks and unintended consequences","type":"textarea","prompt":"Include operational disruption, customer harm, security, compliance, financial exposure, dependency and adoption risks."}]},{"id":"validation_prioritization","title":"6. Validation, feasibility & prioritization inputs","description":"Determine what must be tested and what constraints shape the order of action.","questions":[{"key":"rc_validation_plan","label":"Validation plan and remaining evidence required","type":"textarea","required":true,"prompt":"Specify test, data, sample, owner, timeframe and decision threshold needed to confirm the cause or opportunity."},{"key":"rc_feasibility","label":"Feasibility and organizational readiness","type":"select","required":true,"options":["Ready — ownership, capacity and prerequisites exist","Conditionally ready — manageable gaps or dependencies","Not ready — material capability or capacity gaps","Unknown — requires further assessment"]},{"key":"rc_urgency","label":"Timing and urgency","type":"select","required":true,"options":["Immediate — material near-term risk or time-sensitive opportunity","Near term — address within the next 30–90 days","Medium term — sequence after prerequisite work","Long term — strategic development opportunity","Undetermined — insufficient evidence"]},{"key":"rc_effort","label":"Indicative effort and complexity","type":"select","required":true,"options":["Low — limited scope and dependencies","Moderate — cross-functional coordination required","High — significant change, resources or integration","Major — enterprise-wide or multi-stage transformation","Undetermined — requires scoping"]},{"key":"rc_dependencies_gates","label":"Prerequisites, decision gates and sequencing","type":"textarea","prompt":"Identify approvals, data access, process stabilization, vendor decisions, funding, hiring or other prerequisites."},{"key":"rc_priority_rationale","label":"Priority rationale and trade-offs","type":"textarea","required":true,"prompt":"Explain why this issue/opportunity deserves its proposed priority relative to alternatives, including impact, confidence, effort, risk and strategic fit."}]},{"id":"advisor_synthesis","title":"7. Advisor synthesis & handoff","description":"Create a defensible diagnosis that can feed Instrument 7's prioritization and scenario model.","questions":[{"key":"rc_primary_diagnosis","label":"Primary diagnosis","type":"textarea","required":true,"prompt":"Summarize the strongest evidence-supported explanation, its mechanism, business implications and confidence."},{"key":"rc_secondary_findings","label":"Secondary findings and unresolved hypotheses","type":"textarea","prompt":"List additional findings and hypotheses that should not be represented as established causes."},{"key":"rc_recommendation_direction","label":"Recommended direction of response","type":"textarea","required":true,"prompt":"Describe strategic direction, not a detailed implementation plan. Note what should be stopped, protected, tested or changed."},{"key":"rc_prioritization_inputs","label":"Opportunity inputs for Instrument 7","type":"textarea","required":true,"prompt":"Summarize each candidate opportunity with cause addressed, expected mechanism, evidence confidence, impact indicators, effort, timing, dependencies, risk and owner."},{"key":"rc_open_questions","label":"Open questions and decision points","type":"textarea","prompt":"Identify unresolved choices requiring owner input, additional evidence or specialist review."},{"key":"rc_advisor_confidence","label":"Overall advisor confidence","type":"select","required":true,"options":["High — diagnosis and opportunity logic well supported","Moderate — useful direction with material validation remaining","Low — preliminary assessment only","Insufficient — defer recommendations pending evidence"]}]}],"assessment_policy":"A root cause is not a symptom or a correlation. State causal mechanisms and test alternative explanations. Preserve traceability to Instruments 1–5 and source evidence. Distinguish verified facts, owner/employee reports, advisor hypotheses and conclusions. Do not fabricate financial impact, savings, growth or risk reduction. Missing data is unknown, not poor performance. Consider customer and employee impact, capacity, dependencies, implementation risk and strategic fit."}$schema$::jsonb,
 scoring_definition='{"rating_owner":"advisor","missing_data_policy":"Unknown or unmeasured is not zero or poor performance.","evidence_policy":"Maintain traceability to source evidence and prior instruments; distinguish verified facts, owner-reported information, advisor hypotheses and conclusions.","causality_policy":"Do not equate correlation with causation; document mechanisms and alternative explanations.","impact_policy":"Do not invent financial or operational impact estimates."}'::jsonb,
 published_at=COALESCE(tv.published_at,now())
FROM assessment_templates t
WHERE tv.template_id=t.id AND t.instrument_number=6 AND tv.version_number=t.current_version;